// nodespySocket.js -- WebSocket endpoint for NodeSpy live snoop + chat
//
// Follows the adminLogs.js pattern: raw WebSocketServer registered on
// WsManager's pathMap, not a WsPool/WsConnection (no call session needed).
//
// Auth: one-time Redis token generated by the admin route. Token contains
// the target node number and sysop session ID. Validated on connect,
// deleted immediately (no replay).
//
// Modes:
//   watching: binary frames piped from target's OutputRingBuffer (read-only)
//   chatting: split-screen chat on target, sysop types via JSON messages

import { WebSocketServer } from 'ws';
import * as redis from '../middleware/db/redis.js';
import * as sessionStore from '../middleware/db/sessionstore.js';
import appConfig from '../config/appConfig.js';
import { SplitScreenChat } from '../handlers/splitscreenchat.js';
import * as alogger from '../utils/alogger.js';

var _spyWss = null;

function _checkAdminAccess(user) {
	if (!user) return false;
	var security = parseInt(user.security) || 0;
	if (security < appConfig.getNumber('adminsecurity', 200)) return false;
	var perms = Array.isArray(user.permissionflags) ? user.permissionflags : [];
	return perms.includes('Sysop');
}

async function registerNodeSpyWebSocket(wsManager, callManagerRef) {
	_spyWss = new WebSocketServer({ noServer: true });

	// Register on WsManager's pathMap
	wsManager.pathMap.set('/ws/nodespy', {
		handleUpgrade(request, socket, head) {
			_spyWss.handleUpgrade(request, socket, head, (ws) => {
				_spyWss.emit('connection', ws, request);
			});
		}
	});

	_spyWss.on('connection', async (ws, request) => {
		// Extract token from query string
		var url = new URL(request.url, 'http://localhost');
		var token = url.searchParams.get('token');

		if (!token) {
			ws.close(4001, 'No token');
			return;
		}

		// Read and delete token (one-time use)
		var rc = await redis.getClient();
		var tokenRaw = await rc.get('nodespy:' + token);
		if (!tokenRaw) {
			ws.close(4001, 'Invalid or expired token');
			return;
		}
		await rc.del('nodespy:' + token);

		var tokenData;
		try {
			tokenData = JSON.parse(tokenRaw);
		} catch (_) {
			ws.close(4001, 'Malformed token');
			return;
		}

		// Validate session
		var session = await sessionStore.sessionGet(tokenData.sessionId);
		if (!_checkAdminAccess(session)) {
			ws.close(4003, 'Insufficient permissions');
			return;
		}

		// Look up the target call
		var nodenum = tokenData.nodenum;
		var call = callManagerRef.getCallByNode(nodenum);
		if (!call || !call.outputBuffer) {
			ws.send(Buffer.from('\x1b[2J\x1b[H\x1b[1;31mNode ' + nodenum + ' is not active.\x1b[0m\r\n'));
			ws.close(4004, 'Node not active');
			return;
		}

		var sysopName = session.username || 'Sysop';
		alogger.writeAlog(2, 'NodeSpy: ' + sysopName + ' watching node ' + nodenum, 'cyanbright');

		// --- Session state ---
		var chatActive = false;
		var targetChat = null;       // SplitScreenChat on target's terminal
		var targetPrevRaw = false;
		var targetPrevRawtarget = null;

		// --- Snoop: ring buffer -> WebSocket ---
		var history = call.outputBuffer.getHistory();
		if (history.length > 0) {
			ws.send(history);
		}

		var dataListener = function(buf) {
			if (ws.readyState !== 1) return;
			ws.send(buf);
		};

		var endListener = function() {
			if (chatActive) teardownChat('Session ended');
			if (ws.readyState === 1) {
				ws.send(Buffer.from('\r\n\r\n\x1b[1;33m[Session ended]\x1b[0m\r\n'));
				ws.close(1000, 'Session ended');
			}
		};

		call.outputBuffer.emitter.on('data', dataListener);
		call.outputBuffer.emitter.on('end', endListener);

		// --- Chat functions ---

		function startChat() {
			if (chatActive) return;
			if (!call || !call.cmds) return;

			// Queue if not at menu
			if (call.call_status !== 'menu') {
				call.pendingChat = {
					sysopCall: null,
					callback: function() {
						if (ws.readyState !== 1) return;
						startChat();
					}
				};
				sendJson({ type: 'chat_queued' });
				alogger.writeAlog(2, 'NodeSpy: ' + sysopName + ' queued chat for node ' + nodenum, 'cyan');
				return;
			}

			chatActive = true;
			var targetName = call.caller_username || 'User';

			alogger.writeAlog(2, 'NodeSpy: ' + sysopName + ' started chat with node ' + nodenum, 'cyanbright');

			// Set up target side
			targetPrevRaw = call.rawmode;
			targetPrevRawtarget = call.rawtarget;

			targetChat = new SplitScreenChat(call, {
				sysopLabel: sysopName,
				userLabel: targetName,
				allowExit: false,
				onSend: function(text) {
					targetChat.userMessage(text);
					// Forward to sysop's web client
					sendJson({ type: 'chat_msg', from: 'user', name: targetName, text: text });
				},
				onTyping: function(inputBuf) {
					sendJson({ type: 'chat_typing', text: inputBuf });
				}
			});

			call.rawmode = true;
			call.rawtarget = function(data) {
				if (!targetChat || !targetChat.active) return;
				var buf = Buffer.isBuffer(data) ? data : Buffer.from(data);
				for (var i = 0; i < buf.length; i++) {
					var b = buf[i];
					if (b === 0x0D) targetChat.handleKey('Enter');
					else if (b === 0x08 || b === 0x7F) targetChat.handleKey('Backspace');
					else if (b >= 0x20 && b < 0x7F) targetChat.handleChar(String.fromCharCode(b));
					// ESC ignored -- user cannot exit
				}
			};

			// Beeps
			for (var bi = 0; bi < 5; bi++) {
				(function(delay) {
					setTimeout(function() { if (call.cmds) call.cmds.sendbeep(); }, delay);
				})(bi * 100);
			}

			targetChat.start();

			call.updateNodeStatus('sysop_chat', sysopName);
			sendJson({ type: 'chat_started', targetName: targetName });
		}

		function teardownChat(reason) {
			if (!chatActive) return;
			chatActive = false;

			if (targetChat) {
				if (reason) targetChat._systemMessage(reason);
				targetChat._systemMessage("Chat ended");
				targetChat.stop();
				targetChat = null;
			}

			if (call && call.cmds) {
				call.rawmode = targetPrevRaw;
				call.rawtarget = targetPrevRawtarget;
				targetPrevRaw = false;
				targetPrevRawtarget = null;

				call.cmds.clearscreen();
				call.cmds.resetcolors();
				if (call.currentHandler && call.currentHandler._drawMenu) {
					call.currentHandler._drawMenu();
				}
				call.updateNodeStatus('menu', call.currentMenu || '');
			}

			// Cancel any queued chat
			if (call && call.pendingChat) call.pendingChat = null;

			alogger.writeAlog(2, 'NodeSpy: Chat ended between ' + sysopName + ' and node ' + nodenum, 'cyan');
			sendJson({ type: 'chat_ended', reason: reason || 'Sysop ended chat' });

			// Re-send target's screen to the web viewer
			if (call && call.outputBuffer && ws.readyState === 1) {
				var hist = call.outputBuffer.getHistory();
				if (hist.length > 0) ws.send(hist);
			}
		}

		function sendJson(obj) {
			if (ws.readyState === 1) {
				ws.send(JSON.stringify(obj));
			}
		}

		// --- Handle incoming messages from web client ---
		ws.on('message', function(data) {
			var str = Buffer.isBuffer(data) ? data.toString('utf8') : String(data);

			var msg;
			try { msg = JSON.parse(str); } catch (_) { return; }

			if (msg.type === 'chat_start') {
				startChat();
			} else if (msg.type === 'chat_end') {
				teardownChat();
			} else if (msg.type === 'chat_input' && chatActive && targetChat) {
				// Sysop sent a message line
				var text = (msg.text || '').substring(0, 500);
				if (text.length > 0) {
					targetChat.sysopMessage(text);
					sendJson({ type: 'chat_msg', from: 'sysop', name: sysopName, text: text });
				}
			}
		});

		ws.on('close', function() {
			if (chatActive) teardownChat('Sysop disconnected');
			if (call && call.pendingChat) call.pendingChat = null;
			call.outputBuffer.emitter.removeListener('data', dataListener);
			call.outputBuffer.emitter.removeListener('end', endListener);
			alogger.writeAlog(2, 'NodeSpy: ' + sysopName + ' stopped watching node ' + nodenum, 'cyan');
		});

		ws.on('error', function() {
			if (chatActive) teardownChat('Connection error');
			if (call && call.pendingChat) call.pendingChat = null;
			call.outputBuffer.emitter.removeListener('data', dataListener);
			call.outputBuffer.emitter.removeListener('end', endListener);
		});
	});
}

export { registerNodeSpyWebSocket };
